import type { HostRequestHandlers } from "../../core/kernel/index.js";
import type { SecurityBoundary } from "./boundary.js";
import { armDispatchAssertion, disarmDispatchAssertion } from "./dispatch-assert.js";
import { DOMAIN_REGISTRY, type DomainSpec, guardHandlers } from "./domain-guard.js";

interface InstalledState {
	readonly boundary: SecurityBoundary;
	readonly registry: Readonly<Record<string, DomainSpec>>;
}

let installed: InstalledState | undefined;

/** Arms both attachment points. Idempotent per boundary instance. */
export function registerK3SecurityBoundary(
	boundary: SecurityBoundary,
	registry: Readonly<Record<string, DomainSpec>> = DOMAIN_REGISTRY,
): void {
	installed = { boundary, registry };
	armDispatchAssertion((type) => boundary.record("domain.deny", { type, reason: "unguarded_handler_at_dispatch" }));
}

/** Test-teardown seam; not reachable from the kernel process. */
export function clearK3SecurityBoundary(): void {
	installed = undefined;
	disarmDispatchAssertion();
}

export function getK3SecurityBoundary(): SecurityBoundary | undefined {
	return installed?.boundary;
}

/**
 * Attachment point A2 hook. Identity when the boundary is not installed, so upstream behaviour is
 * bit-identical with the implant removed; a full domain-guarded table when it is.
 */
export function applyK3DomainGuard(handlers: HostRequestHandlers): HostRequestHandlers {
	if (!installed) return handlers;
	const {
		handlers: guarded,
		guarded: wrapped,
		denied,
	} = guardHandlers(handlers, installed.boundary, installed.registry);
	installed.boundary.record("domain.call", {
		phase: "registration",
		guardedTypes: wrapped.length,
		deniedTypes: denied,
	});
	return guarded;
}

